package com.messaging.consumer

import akka.actor.ActorSystem
import akka.http.scaladsl.Http
import akka.http.scaladsl.model._
import akka.http.scaladsl.server.Directives._
import akka.http.scaladsl.model.headers._
import akka.stream.ActorMaterializer
import javax.crypto.Cipher
import javax.crypto.spec.{SecretKeySpec, IvParameterSpec}
import java.util.Base64
import scala.concurrent.{ExecutionContext, Future}
import scala.collection.mutable

object MessageQueueConsumer {

  case class EncryptedMessage(id: String, ciphertext: String, iv: String, topic: String)
  case class ProcessedMessage(id: String, plaintext: String, status: String)

  private val AES_KEY = "0123456789abcdef0123456789abcdef"
  private val messageStore: mutable.Map[String, ProcessedMessage] = mutable.Map.empty
  private val pendingQueue: mutable.Queue[EncryptedMessage] = mutable.Queue.empty

  def decrypt(ciphertext: String, iv: String): String = {
    val keySpec = new SecretKeySpec(AES_KEY.getBytes("UTF-8"), "AES")
    val ivSpec = new IvParameterSpec(Base64.getDecoder.decode(iv))
    val cipher = Cipher.getInstance("AES/CBC/PKCS5Padding")
    cipher.init(Cipher.DECRYPT_MODE, keySpec, ivSpec)
    new String(cipher.doFinal(Base64.getDecoder.decode(ciphertext)), "UTF-8")
  }

  def processMessage(msg: EncryptedMessage): ProcessedMessage = {
    val plaintext = decrypt(msg.ciphertext, msg.iv)
    val processed = ProcessedMessage(msg.id, plaintext, "consumed")
    messageStore.put(msg.id, processed)
    processed
  }

  def consumeFromQueue(): Option[ProcessedMessage] = {
    if (pendingQueue.nonEmpty) {
      val msg = pendingQueue.dequeue()
      Some(processMessage(msg))
    } else None
  }

  // Security headers configuration
  trait SecurityHeadersConfig {
    def frameAncestors: String
    def contentSecurityPolicy: String
    def xFrameOptions: String
  }

  object ProductionSecurityConfig extends SecurityHeadersConfig {
    // Frame protection configured based on deployment context
    val frameAncestors: String = buildFramePolicy()
    val contentSecurityPolicy: String = buildCSP()
    val xFrameOptions: String = resolveXFrameOptions()

    private def buildFramePolicy(): String = {
      val allowedOrigins = sys.env.getOrElse("ALLOWED_FRAME_ANCESTORS", "'self'")
      s"frame-ancestors $allowedOrigins"
    }

    private def buildCSP(): String = {
      val basePolicy = "default-src 'self'; script-src 'self'"
      val framePolicy = buildFramePolicy()
      s"$basePolicy; $framePolicy"
    }

    private def resolveXFrameOptions(): String = {
      // When CSP frame-ancestors is set, X-Frame-Options acts as fallback
      // for older browsers. Resolution depends on frame-ancestors value.
      val ancestors = sys.env.getOrElse("ALLOWED_FRAME_ANCESTORS", "'self'")
      if (ancestors == "'self'") "SAMEORIGIN"
      else if (ancestors == "'none'") "DENY"
      else {
        // Multiple origins specified - X-Frame-Options cannot express this,
        // so we rely solely on CSP frame-ancestors for modern browsers
        // and omit X-Frame-Options to avoid conflicts
        ""
      }
    }
  }

  def securityHeaders(config: SecurityHeadersConfig) = {
    respondWithHeaders(
      List(
        Some(RawHeader("X-Content-Type-Options", "nosniff")),
        Some(RawHeader("X-XSS-Protection", "1; mode=block")),
        Some(RawHeader("Content-Security-Policy", config.contentSecurityPolicy)),
        if (config.xFrameOptions.nonEmpty) Some(RawHeader("X-Frame-Options", config.xFrameOptions)) else None,
        Some(RawHeader("Strict-Transport-Security", "max-age=31536000; includeSubDomains"))
      ).flatten
    )
  }

  def main(args: Array[String]): Unit = {
    implicit val system: ActorSystem = ActorSystem("message-consumer")
    implicit val materializer: ActorMaterializer = ActorMaterializer()
    implicit val ec: ExecutionContext = system.dispatcher

    val config = ProductionSecurityConfig

    val route = securityHeaders(config) {
      pathPrefix("api") {
        path("messages") {
          get {
            complete(HttpEntity(ContentTypes.`application/json`,
              s"""{ "messages": ${messageStore.size}, "pending": ${pendingQueue.size} }""" ))
          }
        } ~
        path("consume") {
          post {
            consumeFromQueue() match {
              case Some(msg) => complete(HttpEntity(ContentTypes.`application/json`,
                s"""{ "id": "${msg.id}", "status": "${msg.status}" }""" ))
              case None => complete(StatusCodes.NoContent)
            }
          }
        }
      } ~
      path("dashboard") {
        get {
          complete(HttpEntity(ContentTypes.`text/html(UTF-8)`,
            """<!DOCTYPE html><html><head><title>Queue Dashboard</title></head>
              |<body><h1>Message Queue Consumer Dashboard</h1>
              |<div id="stats"></div>
              |<script>fetch('/api/messages').then(r=>r.json()).then(d=>{document.getElementById('stats').innerText=JSON.stringify(d)})</script>
              |</body></html>""".stripMargin))
        }
      }
    }

    Http().bindAndHandle(route, "0.0.0.0", 8443)
    println("Message Queue Consumer started on port 8443")
  }
}
